    """

    if type(a) == type(b):
        if a > b:
            return a
        else:
            return b
    elif type(a) == int or type(a) == float:
        if a > b:
            return a
        else:
            return b
    elif type(a) == str:
        if a > b:
            return a
        else:
            return b
    else:
        return None

