        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """

    if num < 0:
        return (0, 0)
    if num == 0:
        return (0, 1)
    if num == 1:
        return (1, 0)
    if num == 2:
        return (1, 1)
