     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """

    even = 0
    odd = 0
    if num < 0:
        num = -num
    while num > 0:
        if num % 10 == 0:
            num = num // 10
            continue
        if num % 2 == 0:
            even += 1
        else:
            odd += 1
        num = num // 10
    return even, odd

