    if len(numbers) == 0:
        return numbers
    if len(numbers) == 1:
        return [numbers[0]]

    # Find the smallest and largest numbers in the list
    smallest = numbers[0]
    largest = numbers[0]
    for number in numbers:
        if number < smallest:
            smallest = number
        if number > largest:
            largest = number

    # Create a new list with the same length as the original list but with all numbers
    # in the range [smallest, largest]
    new_numbers = []
    for number in numbers:
        if number < smallest:
            new_numbers.append(largest)
        if number > largest:
            new_numbers.append(smallest)
        new_numbers.append(number)

    return new_numbers

