    True
    >>> is_palindrome('aba')
    True
    >>> is_palindrome('aaaaa')
    True
    >>> is_palindrome('zbcd')
    False
    """

    if len(text) <= 1:
        return True
    else:
        if text[0] == text[-1]:
            return is_palindrome(text[1:-1])
        else:
            return False

